#include "FlightComponent.h"
#include "GameFramework/Actor.h"
#include "Kismet/KismetMathLibrary.h"

UFlightComponent::UFlightComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer),
	FuelCapacityLiters(10000.0f), MaxSpeed(200.0f), ThrustAcceleration(50.0f), TurnRate(90.0f), InertiaDamping(0.98f)
{
	PrimaryComponentTick.bCanEverTick = true;
}

void UFlightComponent::InitializeFromShip(float CapacityLiters, float ConsumptionRate, float QuantumFuelCost, float QuantumTravelTime)
{
	this->FuelCapacityLiters = CapacityLiters;
	UE_LOG(LogTemp, Log, TEXT("FlightComponent initialized: FuelCapacity=%.1fL, MaxSpeed=%.1f, Thrust=%.1f"), this->FuelCapacityLiters, MaxSpeed, ThrustAcceleration);
}

void UFlightComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
	Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

	if (!GetOwner()) return;

	// === FIX 3: Flight Physics Movement Component ===
	// Thrust comes from bound input (ThrustAxis, set by ship possession).
	// tb-0189: NEVER default to full thrust - a hardcoded 1.0f here made
	// every carrier climb forever (the pawn-levitation bug).
	float ThrustInput = ThrustAxis;
	float PitchInput = 0.0f;
	float YawInput = 0.0f;
	float RollInput = 0.0f;

	// Apply thrust along ship forward direction
	FVector Acceleration = GetOwner()->GetActorForwardVector() * ThrustAcceleration * ThrustInput;
	CurrentVelocity += Acceleration * DeltaTime;

	// Apply damping when not thrusting (inertia)
	if (ThrustInput <= 0.0f)
	{
		CurrentVelocity *= FMath::Pow(InertiaDamping, DeltaTime * 60.0f);
	}

	// Clamp to max speed
	float Speed = CurrentVelocity.Size();
	if (Speed > MaxSpeed)
	{
		CurrentVelocity = CurrentVelocity.GetSafeNormal() * MaxSpeed;
	}

	// Apply rotation (pitch, yaw, roll)
	FRotator RotationDelta = GetOwner()->GetActorRotation();
	RotationDelta.Yaw += TurnRate * YawInput * DeltaTime;
	RotationDelta.Pitch += TurnRate * PitchInput * DeltaTime;
	RotationDelta.Roll += TurnRate * RollInput * DeltaTime;

	// Move the ship
	FVector NewLocation = GetOwner()->GetActorLocation() + CurrentVelocity * DeltaTime;
	GetOwner()->SetActorLocation(NewLocation);

	// Log movement for verification (every 60 ticks = ~1 second)
	static int32 TickCount = 0;
	if (++TickCount % 60 == 0 && Speed > 1.0f)
	{
		UE_LOG(LogTemp, Log, TEXT("FlightComponent: Speed=%.1f, Location=%s"), Speed, *NewLocation.ToString());
	}
}

